473	fn prompt_multiselect(
474	    prompt: &Prompt,
475	    options: &[PromptOption],
476	    term: &Term,
477	) -> Result<PromptResult> {
478	    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
479	
480	    let default_values: Vec<&str> = prompt
481	        .default
482	        .as_deref()
483	        .map(|d| d.split(',').collect())
484	        .unwrap_or_default();
485	    let defaults: Vec<bool> = options
486	        .iter()
487	        .map(|o| default_values.contains(&o.value.as_str()))
488	        .collect();
489	
490	    let multiselect_theme = ColorfulTheme {
491	        prompt_suffix: style("".to_string()),
492	        ..prompt_theme()
493	    };
494	
495	    // Print prompt question and hint text for keyboard controls
496	    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
497	    term.write_line(&format!(
498	        "{}",
499	        style("[space] toggle · [a] toggle all · [enter] confirm").dim()
500	    ))
501	    .map_err(BivvyError::Io)?;
502	
503	    let selections = MultiSelect::with_theme(&multiselect_theme)
504	        .items(&labels)
505	        .defaults(&defaults)
506	        .interact_on(term)
507	        .map_err(map_dialoguer_err)?;
508	
509	    let values: Vec<String> = selections
510	        .iter()
511	        .map(|&i| options[i].value.clone())
512	        .collect();
513	
514	    Ok(PromptResult::Strings(values))
515	}
