1	//! Rerun window — how long a previous successful run counts as "recent enough"
2	//! to consider a step satisfied.
3	//!
4	//! The rerun window is a duration that defines when execution history alone is
5	//! sufficient to skip a step. Outside the window, the step must be re-evaluated
6	//! via checks or re-run.
7	//!
8	//! # Parsing
9	//!
10	//! Accepts human-readable duration strings:
11	//! - `"4h"` — 4 hours
12	//! - `"30m"` — 30 minutes
13	//! - `"7d"` — 7 days
14	//! - `"0"` or `"never"` — execution history never satisfies this step
15	//! - `"forever"` — a previous successful run always counts
16	//!
17	//! # Default
18	//!
19	//! The default rerun window is 4 hours.
20	
21	use std::fmt;
22	use std::str::FromStr;
23	
24	use chrono::{DateTime, Utc};
25	use serde::{Deserialize, Serialize};
26	
27	/// How long a previous successful run counts as "recent enough" to satisfy a step.
28	#[derive(Debug, Clone, PartialEq, Eq)]
29	pub enum RerunWindow {
30	    /// A fixed duration window. The step is satisfied if it ran successfully
31	    /// within this duration.
32	    Duration(std::time::Duration),
33	
34	    /// Execution history never satisfies this step. It must be satisfied by
35	    /// checks or `satisfied_when`, or it auto-runs every time.
36	    Never,
37	
38	    /// A previous successful run always counts. Equivalent to an infinite window.
39	    Forever,
40	}
41	
42	impl RerunWindow {
43	    /// Default rerun window: 4 hours.
44	    pub const DEFAULT_HOURS: u64 = 4;
45	
46	    /// Check whether a timestamp falls within this rerun window.
47	    ///
48	    /// Returns `true` if the given `recorded_at` time is recent enough to be
49	    /// considered valid according to this window.
50	    pub fn is_within_window(&self, recorded_at: DateTime<Utc>) -> bool {
51	        match self {
52	            RerunWindow::Never => false,
53	            RerunWindow::Forever => true,
54	            RerunWindow::Duration(dur) => {
55	                let elapsed = Utc::now().signed_duration_since(recorded_at);
56	                // If recorded_at is in the future (clock skew), treat as within window
57	                if elapsed.num_milliseconds() < 0 {
58	                    return true;
59	                }
60	                let elapsed_std = elapsed.to_std().unwrap_or(std::time::Duration::MAX);
61	                elapsed_std <= *dur
62	            }
63	        }
64	    }
65	}
66	
67	impl Default for RerunWindow {
68	    fn default() -> Self {
69	        RerunWindow::Duration(std::time::Duration::from_secs(Self::DEFAULT_HOURS * 3600))
70	    }
71	}
