116	impl SpinnerFactory for NonInteractiveUI {
117	    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
118	        if self.mode.shows_spinners() {
119	            println!("  {}", message);
120	        }
121	        Box::new(NoopSpinner { indent: 0 })
122	    }
123	
124	    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
125	        if self.mode.shows_spinners() {
126	            let prefix = " ".repeat(indent);
127	            println!("{}{}", prefix, message);
128	        }
129	        Box::new(NoopSpinner { indent })
130	    }
131	}
