161	/// Spinner that does nothing (for non-interactive mode).
162	struct NoopSpinner {
163	    indent: usize,
164	}
165	
166	impl SpinnerHandle for NoopSpinner {
167	    fn set_message(&mut self, _msg: &str) {}
168	
169	    fn finish_success(&mut self, msg: &str) {
170	        let prefix = " ".repeat(self.indent);
171	        let theme = BivvyTheme::new();
172	        println!("{}{}", prefix, theme.format_success(msg));
173	    }
174	
175	    fn finish_error(&mut self, msg: &str) {
176	        let prefix = " ".repeat(self.indent);
177	        let theme = BivvyTheme::new();
178	        println!("{}{}", prefix, theme.format_error(msg));
179	    }
180	
181	    fn finish_skipped(&mut self, msg: &str) {
182	        let prefix = " ".repeat(self.indent);
183	        let theme = BivvyTheme::new();
184	        println!("{}{}", prefix, theme.format_skipped(msg));
185	    }
186	
187	    fn finish_and_clear(&mut self) {
188	        // No-op for non-interactive: nothing to clear
189	    }
190	}
